// Native embedder-only, one immutable callback, invoked after the actual main
// loop and all its members have been destroyed, never on window/profile close.
CONTENT_EXPORT bool RegisterBrowserShutdownCompletion(void (*completed)());
CONTENT_EXPORT void ObserveBrowserMainLoopDestroyedForDrain();

namespace content::aux_migration {
namespace {
std::atomic<void (*)()> completion{nullptr};
std::atomic_bool delivered{false};
}
bool RegisterBrowserShutdownCompletion(void (*completed)()) {
  if (!completed || delivered.load()) return false;
  void (*expected)() = nullptr;
  return completion.compare_exchange_strong(expected, completed) || expected == completed;
}
void ObserveBrowserMainLoopDestroyedForDrain() {
  if (delivered.exchange(true)) return;
  if (auto completed = completion.load()) completed();
}

void FinishNativeBrowserShutdownDrain() {
  auto& state = State();
  {
    std::lock_guard<std::mutex> lock(state.mutex);
    if (getpid() != state.process || !state.started || state.main_loop_destroyed) return;
    state.main_loop_destroyed = true;
  }
